LayoutObject.LocalCSS:
self:normal .self
{
	text-align: left;
}
self:normal .icon
{
	background-position: left center;
}

self:normal .self
{
	font-size: 13pt;
	color: rgba(100%,100%,100%,1);
	text-align: left;
	-fm-text-vertical-align: top;
}
self:pressed .self
{
	background-image: none;
	background-color: rgba(60.3922%,60.3922%,60.3922%,1);
	border-image-source: none;
	color: rgba(90.1961%,90.1961%,90.1961%,1);
}
self:focus .self
{
	border-top-color: rgba(100%,100%,100%,0);
	border-right-color: rgba(100%,100%,100%,0);
	border-bottom-color: rgba(100%,100%,100%,0);
	border-left-color: rgba(100%,100%,100%,0);
	border-top-style: none;
	border-right-style: none;
	border-bottom-style: none;
	border-left-style: none;
	border-top-width: 0pt;
	border-right-width: 0pt;
	border-bottom-width: 0pt;
	border-left-width: 0pt;
}
self:normal .inner_border
{
	padding-top: 2pt;
	padding-right: 0pt;
	padding-bottom: 0pt;
	padding-left: 1pt;
}
self:normal .icon
{
	background-position: left top;
	-fm-icon-color: rgba(100%,100%,100%,1);
}
self:pressed .icon
{
	-fm-icon-color: rgba(90.1961%,90.1961%,90.1961%,1);
